// === Validate Request Schema — Webhook v2 Body Normalization ===
// Handles both direct payload and webhook-v2 body-wrapped payload.
// Produces structured fail-closed error codes. No silent fallbacks.

const inputItem = $input.first();
if (!inputItem) {
  return [{ json: { status: 'FAILED', stage: 'VALIDATE_REQUEST', error: { code: 'INPUT_ITEM_MISSING', message: 'No input item received' }, timestamp: new Date().toISOString() } }];
}

const envelope = inputItem.json;
if (!envelope || typeof envelope !== 'object' || Array.isArray(envelope)) {
  return [{ json: { status: 'FAILED', stage: 'VALIDATE_REQUEST', error: { code: 'INPUT_NOT_OBJECT', message: 'Input is not a valid JSON object' }, timestamp: new Date().toISOString() } }];
}

// Normalize: webhook v2 wraps payload under json.body
const hasObjectBody =
  Object.prototype.hasOwnProperty.call(envelope, 'body') &&
  envelope.body !== null &&
  typeof envelope.body === 'object' &&
  !Array.isArray(envelope.body);

const payload = hasObjectBody ? envelope.body : envelope;

// Shell injection guard - detect dangerous shell metacharacters
const shellChars = /[;&|><`\(\)\{\}\[\]\*\?]/;
const stringFields = ['project_id', 'repository', 'requested_ref', 'correlation_id', 'hostname', 'build_profile', 'request_class'];
for (const field of stringFields) {
  if (typeof payload[field] === 'string' && shellChars.test(payload[field])) {
    errors.push({ code: 'SHELL_INJECTION_DETECTED', field: field, message: 'Shell metacharacter detected in ' + field });
  }
}
// Schema validation
const required = ['project_id', 'repository', 'requested_ref', 'correlation_id', 'idempotency_key', 'template_id', 'template_version'];
const errors = [];
for (const field of required) {
  if (!payload[field]) {
    errors.push({ code: 'REQUIRED_FIELD_MISSING', field: field, message: 'Missing required field: ' + field });
  }
}

// --- sata-local Contract Enforcement ---
if (payload.target_storage && payload.target_storage !== 'sata-local') {
  errors.push({ code: 'INVALID_TARGET_STORAGE', field: 'target_storage', message: 'Only sata-local storage is allowed', received: payload.target_storage });
}
if (payload.clone_mode && payload.clone_mode !== 'linked') {
  errors.push({ code: 'INVALID_CLONE_MODE', field: 'clone_mode', message: 'Only linked clone mode is allowed', received: payload.clone_mode });
}
if (payload.template_id && payload.template_id !== 112) {
  errors.push({ code: 'INVALID_TEMPLATE_ID', field: 'template_id', message: 'Only template CT 112 (sata-local) is allowed. CT 111 is deprecated.', received: payload.template_id });
}

if (errors.length > 0) {
  return [{ json: {
    status: 'FAILED',
    stage: 'VALIDATE_REQUEST',
    validation: 'FAILED',
    errors: errors,
    correlation_id: payload.correlation_id || 'UNKNOWN',
    timestamp: new Date().toISOString()
  } }];
}

return [{ json: {
  status: 'PASSED',
  stage: 'VALIDATE_REQUEST', 
  validation: 'PASSED',
  project_id: payload.project_id,
  repository: payload.repository,
  requested_ref: payload.requested_ref,
  correlation_id: payload.correlation_id,
  idempotency_key: payload.idempotency_key,
  template_id: payload.template_id || 112,
  template_version: payload.template_version || 'v0.6.0',
  target_node: payload.target_node || 'pve',
  target_storage: payload.target_storage || 'sata-local',
  clone_mode: payload.clone_mode || 'linked',
  max_containers: payload.max_containers || 1,
  dry_run: payload.dry_run || false,
  hostname: payload.hostname,
  build_profile: payload.build_profile || 'default',
  request_class: payload.request_class || 'standard',
  timestamp: new Date().toISOString()
} }];

const data = $input.first().json;
if (data.validation === 'FAILED') {
  return [{ json: { route: 'INVALID_REQUEST', errors: data.errors, correlation_id: data.correlation_id || 'UNKNOWN', timestamp: data.timestamp || new Date().toISOString() } }];
}
return [{ json: { route: 'VALID_REQUEST', ...data } }];

// Stage 3: Idempotency Gate — CRITICAL ROUTING
// Check if this idempotency key was already processed.
// Returns cached result if found, otherwise signals NEW_REQUEST.

const data = $input.first().json;

// This node will be connected to SSH: Registry Idempotency Check
// For now, mark as PENDING_IDEMPOTENCY_CHECK — the SSH node result will determine routing
return {
  ...data,
  idempotency_status: 'PENDING_CHECK',
  stage: 'IDEMPOTENCY_GATE'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let cached = false;
try { const r = JSON.parse(stdout); cached = r.status === 'DUPLICATE' || r.idempotent === true; } catch(e) {}

if (cached) {
  try {
    const result = JSON.parse(stdout);
    return [
      { json: { route: 'ALREADY_PROCESSED', cached_result: result, correlation_id: data.correlation_id } },
      { json: {} }
    ];
  } catch(e) {
    return [
      { json: { route: 'ALREADY_PROCESSED', raw_stdout: stdout } },
      { json: {} }
    ];
  }
}
return [
  { json: {} },
  { json: { route: 'NEW_REQUEST', stage: 'DISCOVERING', run_id: 'n8n-provisioning-' + Date.now() } }
];

const data = $input.first().json;
if (!data.cached_result && !data.route) { return []; }
return [{ json: { status: 'ALREADY_PROCESSED', correlation_id: data.correlation_id || 'UNKNOWN', cached_result: data.cached_result || data.raw_stdout, timestamp: new Date().toISOString() } }];

// Stage 4: Prepare Registry Discovery
// Records idempotency key and prepares for project lookup

const data = $input.first().json;

return {
  ...data,
  stage: 'DISCOVERING',
  run_id: `n8n-provisioning-${Date.now()}`
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let discoveryResult;
try { discoveryResult = JSON.parse(stdout); } catch(e) { discoveryResult = { status: 'ERROR', error: 'Failed to parse registry response' }; }

if (discoveryResult.status === 'ALREADY_EXISTS') {
  if (discoveryResult.state === 'READY' || discoveryResult.state === 'SUCCEEDED') {
    return [
      { json: { route: 'PROJECT_READY', discovery: discoveryResult, ctid: discoveryResult.ctid, hostname: discoveryResult.hostname } },
      { json: {} }
    ];
  }
  return [
    { json: { route: 'PROJECT_EXISTS_NOT_READY', error: 'Project exists in state: ' + (discoveryResult.state || 'unknown') } },
    { json: {} }
  ];
}
if (discoveryResult.status === 'NEW_PROJECT') {
  return [
    { json: {} },
    { json: { route: 'PROJECT_NEW', discovery: discoveryResult } }
  ];
}
return [
  { json: { route: 'DISCOVERY_FAILED', error: discoveryResult.error || 'Unknown discovery error' } },
  { json: {} }
];

const data = $input.first().json;
if (!data.ctid && !data.route) { return []; }
return [{ json: { ctid: data.ctid, hostname: data.hostname, stage: 'REUSE_READY' } }];

// Stage 6: Prepare Proxmox Reconcile
// Verify registry state against Proxmox reality

const data = $input.first().json;
return {
  ...data,
  stage: 'RECONCILING'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let reconcileResult;
try { reconcileResult = JSON.parse(stdout); } catch(e) { return [{ json: { } }, { { json: { route: 'RECONCILE_FAILED', error: 'Failed to parse Proxmox response', stdout: stdout } } }];; }
if (reconcileResult.operation !== 'reconcile' || reconcileResult.status !== 'SUCCEEDED') {
  return [{ json: { } }, { { json: { route: 'RECONCILE_FAILED', error: (reconcileResult.error || 'Reconcile returned non-success'), result: reconcileResult } } }];;
}
if (!reconcileResult.template_exists) {
  return [{ json: { } }, { { json: { route: 'TEMPLATE_MISSING', error: 'Golden template not found' } } }];;
}
const thinPool = reconcileResult.thin_pool || {};
const dataPct = parseFloat(thinPool.data_percent || '100');
if (dataPct > 90) {
  return [{ json: { } }, { { json: { route: 'STORAGE_EXHAUSTED', error: 'Thin pool data at ' + dataPct + '%', thin_pool: thinPool } } }];;
}
return [{ json: { route: 'TEMPLATE_AND_STORAGE_OK', reconcile: reconcileResult } }, { json: {} }];

// Gate: Approval — route APPROVED vs REQUIRED
const data = $input.first().json;

// Canary projects are auto-approved
const isCanary = (data.project_id || '').startsWith('n8n-spec-kit-canary') ||
                 (data.request_class || '') === 'canary';
const approvalStatus = isCanary ? 'APPROVED' : 'APPROVAL_REQUIRED';

const result = {
  approval: approvalStatus,
  project_id: data.project_id,
  run_id: data.run_id,
  template_id: data.template_id || 112,
  template_version: data.template_version || 'v0.6.0'
};

// Branch 0: APPROVED (continue)
// Branch 1: APPROVAL_REQUIRED (stop)
if (approvalStatus === 'APPROVED') {
  return [{ json: result }, { json: {} }];
} else {
  return [{ json: {} }, { json: { approval: 'APPROVAL_REQUIRED', error: 'Production provisioning requires approval token' } }];
}

// Stage 9: Atomic CTID Allocation under Lease

const data = $input.first().json;

return {
  ...data,
  stage: 'ALLOCATING'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let allocResult;
try { allocResult = JSON.parse(stdout); } catch(e) { return [{ json: {} }, { json: { route: 'ALLOCATION_FAILED', error: 'Failed to parse allocation response' } }]; }
if (allocResult.status === 'ALLOCATED') {
  return [{ json: { route: 'ALLOCATED', ctid: allocResult.ctid } }, { json: {} }];
}
return [{ json: {} }, { json: { route: 'ALLOCATION_FAILED', error: allocResult.error || 'Unknown allocation error' } }];

// Stage 11: Prepare Linked Clone from CT 111

const data = $input.first().json;
const hostname = data.hostname || `${data.project_id.replace(/[^a-zA-Z0-9-]/g, '-').substring(0, 20)}-build`;

return {
  ...data,
  hostname: hostname,
  stage: 'CLONING'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let cloneResult;
try { cloneResult = JSON.parse(stdout); } catch(e) { return [{ json: { route: 'CLONE_FAILED', error: 'Failed to parse clone response' } }, { json: {} }]; }
if (cloneResult.status === 'SUCCEEDED') {
  return [{ json: {} }, { json: { route: 'CLONE_SUCCEEDED', clone: cloneResult } }];
}
return [{ json: { route: 'CLONE_FAILED', error: cloneResult.error || 'Clone operation failed' } }, { json: {} }];

// Stage 12: Prepare Network Isolation Installation

const data = $input.first().json;

return {
  ...data,
  stage: 'NETWORK_ISOLATION'
};

// Stage 13: Container Initialization
// Set hostname, start network, configure DNS

const data = $input.first().json;

return {
  ...data,
  stage: 'INITIALIZING'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let initResult;
try { initResult = JSON.parse(stdout); } catch(e) { return [{ json: { route: 'INIT_FAILED', error: 'Failed to parse init response' } }, { json: {} }]; }
if (!initResult.ready) {
  return [{ json: { route: 'NOT_READY', error: initResult.error || 'Container not ready', details: initResult } }, { json: {} }];
}
if (!initResult.firewall_active) {
  return [{ json: { route: 'NOT_READY', error: 'Firewall not active', details: initResult } }, { json: {} }];
}
return [{ json: {} }, { json: { route: 'READY', ctid: initResult.ctid, hostname: initResult.hostname, init: initResult } }];

const data = $input.first().json;
if (!data.error && !data.route) { return []; }
return [{ json: { error: data.error || 'Container failed readiness gate', details: data.details } }];

// Stage 15: Registry → READY
const data = $input.first().json;
return {
  ...data,
  stage: 'REGISTERING'
};

// Stage 16: Prepare Build — via separate Build Adapter
// Build must NOT start before READY

const data = $input.first().json;
const buildId = `build-${data.project_id}-${Date.now()}`;

return {
  ...data,
  build_id: buildId,
  stage: 'BUILD_QUEUED'
};

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let buildResult;
try { buildResult = JSON.parse(stdout); } catch(e) { return [{ json: {} }, { json: { route: 'BUILD_LAUNCH_FAILED', error: 'Failed to parse build-start response' } }]; }
if (buildResult.status === 'BUILD_LAUNCHED') {
  return [{ json: { route: 'BUILD_LAUNCHED', build_id: buildResult.build_id, build: buildResult } }, { json: {} }];
}
return [{ json: {} }, { json: { route: 'BUILD_LAUNCH_FAILED', error: buildResult.error || 'Build did not launch' } }];

const data = $input.first().json;
const stdout = (data.stdout || '').toString();
let statusResult;
try { statusResult = JSON.parse(stdout); } catch(e) { return [{ json: { route: 'BUILD_STATUS_UNKNOWN', error: 'Failed to parse build status' } }, { json: {} }]; }
if (statusResult.status === 'BUILD_SUCCEEDED') {
  return [{ json: {} }, { json: { route: 'BUILD_SUCCEEDED', build: statusResult } }];
}
if (statusResult.status === 'BUILD_RUNNING') {
  return [{ json: { route: 'BUILD_RUNNING', build: statusResult } }, { json: {} }];
}
return [{ json: { route: 'BUILD_FAILED', build: statusResult, error: statusResult.error || 'Build failed' } }, { json: {} }];

// Stage 17c: BUILD_RUNNING — loop back to wait
const data = $input.first().json;
return {
  route: 'BUILD_RUNNING',
  build: data.build,
  wait_again: true
};

const data = $input.first().json;
const build = data.build || {};
const artifacts = build.artifacts || {};
if (artifacts.sha256) {
  const sha256Regex = /^[a-fA-F0-9]{64}$/;
  if (!sha256Regex.test(artifacts.sha256)) {
    return [{ json: { route: 'ARTIFACT_INVALID', error: 'Invalid artifact SHA256: ' + artifacts.sha256 } }, { json: {} }];
  }
}
return [{ json: {} }, { json: { route: 'ARTIFACT_VALID', artifact_sha256: artifacts.sha256, test_passed: build.test_passed || 0, test_total: build.test_total || 0 } }];

const data = $input.first().json;
if (!data.error && !data.route) { return []; }
return [{ json: { error: data.error } }];

// Stage 19: Evidence Seal
// Record success in registry and prepare final evidence

const data = $input.first().json;

return {
  ...data,
  stage: 'EVIDENCE_SEAL',
  completed_at: new Date().toISOString()
};

// Stage 20: Final Result Assembly
// CRITICAL: All code-node routing throughout

const data = $input.first().json;
const buildData = $('Validate Artifact').first().json || {};

return {
  json: {
    status: 'SUCCEEDED',
    correlation_id: data.correlation_id,
    project_id: data.project_id,
    ctid: data.ctid,
    hostname: data.hostname,
    build_id: data.build_id,
    artifact_sha256: buildData.artifact_sha256,
    test_passed: buildData.test_passed,
    test_total: buildData.test_total,
    run_id: data.run_id,
    completed_at: data.completed_at || new Date().toISOString()
  }
};

const data = $input.first().json;

const isDryRun = data.dry_run === true || data.dry_run === 'true';
const isInvalid = data.route === 'INVALID_REQUEST';

let route;
if (isInvalid) {
  route = 'INVALID';
} else if (isDryRun) {
  route = 'DRY_RUN';
} else {
  route = 'PROCEED';
}

return [{
  json: {
    route: route,
    request: {
      project_id: data.project_id,
      repository: data.repository,
      requested_ref: data.requested_ref,
      template_id: data.template_id || 112,
      template_version: data.template_version || 'v0.6.0',
      target_storage: data.target_storage || 'sata-local',
      target_node: data.target_node || 'pve',
      clone_mode: data.clone_mode || 'linked',
      max_containers: data.max_containers || 1,
      dry_run: data.dry_run || false,
      hostname: data.hostname,
      build_profile: data.build_profile || 'default',
      request_class: data.request_class || 'standard'
    },
    errors: (data.errors && data.errors.length > 0) ? data.errors : null,
    correlation_id: data.correlation_id || 'UNKNOWN',
    idempotency_key: data.idempotency_key,
    template_id: data.template_id || 112,
    template_version: data.template_version || 'v0.6.0',
    target_storage: data.target_storage || 'sata-local',
    target_node: data.target_node || 'pve',
    clone_mode: data.clone_mode || 'linked',
    max_containers: data.max_containers || 1,
    dry_run: data.dry_run || false,
    hostname: data.hostname,
    build_profile: data.build_profile || 'default',
    request_class: data.request_class || 'default',
    timestamp: new Date().toISOString(),
    validation: data.validation,
    status: data.status,
    stage: data.stage
  }
}];

const item = $input.first();

if (!item?.json) {
  throw new Error("Gate Provisioning: ROUTING_INPUT_MISSING");
}

if (item.json.route === "PROCEED") {
  return [item];
}

if (item.json.route === "INVALID" || item.json.route === "DRY_RUN") {
  return [];
}

throw new Error("Gate Provisioning: UNKNOWN_ROUTE: " + (item.json.route || "undefined"));

const item = $input.first();

if (!item?.json) {
  throw new Error("Gate Invalid Response: ROUTING_INPUT_MISSING");
}

if (item.json.route === "INVALID") {
  return [item];
}

if (item.json.route === "DRY_RUN" || item.json.route === "PROCEED") {
  return [];
}

throw new Error("Gate Invalid Response: UNKNOWN_ROUTE: " + (item.json.route || "undefined"));

const item = $input.first();

if (!item?.json) {
  throw new Error("Gate Dry Run Response: ROUTING_INPUT_MISSING");
}

if (item.json.route === "DRY_RUN") {
  return [item];
}

if (item.json.route === "INVALID" || item.json.route === "PROCEED") {
  return [];
}

// Unknown route: return empty, no mutation
return [];
